import{_ as l,c as e,o as r,ag as i}from"./chunks/framework.Bkod66qp.js";const b=JSON.parse('{"title":"소송사무 처리에 관한 내규","description":"","frontmatter":{"title":"소송사무 처리에 관한 내규","subtitle":"","doc_id":"","last_update":"2022-05-26","author":"","categories":[],"tags":[]},"headers":[],"relativePath":"regulation/613_소송사무 처리에 관한 내규(220526).md","filePath":"regulation/613_소송사무 처리에 관한 내규(220526).md"}'),o={name:"regulation/613_소송사무 처리에 관한 내규(220526).md"};function d(p,t,a,s,n,x){return r(),e("div",null,t[0]||(t[0]=[i('<h1 id="law-title" class="center" tabindex="-1">소송사무 처리에 관한 내규 <a class="header-anchor" href="#law-title" aria-label="Permalink to &quot;소송사무 처리에 관한 내규 {#law-title .center}&quot;">​</a></h1><div style="text-align:right;"><pre style="display:inline-block;margin:0;white-space:pre;font-family:monospace;">제정 2022.   5.  26</pre></div><h2 id="제1장-총칙" tabindex="-1">제1장 총칙 <a class="header-anchor" href="#제1장-총칙" aria-label="Permalink to &quot;제1장 총칙&quot;">​</a></h2><h2 id="article1" class="sr-only" tabindex="-1">제1조 (목적) <a class="header-anchor" href="#article1" aria-label="Permalink to &quot;제1조 (목적) {#article1 .sr-only}&quot;">​</a></h2><p><strong>제1조(목적)</strong> 이 내규는 서울문화재단 각 소관부서의 소송사무 처리에 관해 필요한 사항을 정하여 소송의 효율적인 수행과 적정한 관리 도모를 목적으로 한다.</p><h2 id="article2" class="sr-only" tabindex="-1">제2조 (정의) <a class="header-anchor" href="#article2" aria-label="Permalink to &quot;제2조 (정의) {#article2 .sr-only}&quot;">​</a></h2><p><strong>제2조(정의)</strong> 이 내규에서 사용하는 용어의 정의는 다음과 같다.</p><ol><li>“소송”이란 재단이 당사자(참가자 포함)가 되는 민사소송(신청사건 포함), 형사소송, 행정소송(신청사건 포함), 행정심판, 중재 및 비송 등의 사건과 재단의 임직원이 재단의 업무수행과 관련하여 직무상 귀책사유 없이 당사자가 된 민사소송 또는 형사소송을 말한다.</li><li>“소관부서”란 소송 관련 사무 업무가 발생하여 이를 처리하거나 전담하는 부서를 말한다.</li><li>“소송대리인”이란 직접 재판상의 행위를 수행하기 위하여 재단으로부터 필요한 권한을 위임받은 변호사 , 법무법인 또는 직원을 말한다.</li><li>“소송수행자”란 소송사무업무를 진행하는 소관부서의 장 혹은 사건을 수임하여 진행하는 소송대리인을 말한다.</li><li>“소송비용”이란 실제 지출 또는 사용된 변호사 비용, 인지대, 송달료, 검증료, 감정료 등 서울문화재단 소송 수행에 소요된 비용을 말한다.</li></ol><h2 id="article3" class="sr-only" tabindex="-1">제3조 (적용대상) <a class="header-anchor" href="#article3" aria-label="Permalink to &quot;제3조 (적용대상) {#article3 .sr-only}&quot;">​</a></h2><p><strong>제3조(적용대상)</strong> 서울문화재단의 소송업무에 관하여 관계법령, 조례, 정관 및 다른 규정에 특별한 규정이 있는 경우를 제외하고는 본 내규에서 정하는 바에 따른다.</p><h2 id="article4" class="sr-only" tabindex="-1">제4조 (소송대리인의 선임) <a class="header-anchor" href="#article4" aria-label="Permalink to &quot;제4조 (소송대리인의 선임) {#article4 .sr-only}&quot;">​</a></h2><p><strong>제4조(소송대리인의 선임)</strong> ① 대표이사는 소송사건이 다음 각 호에 해당하는 경우 또는 소송사건의 규모, 내용, 난이도 등을 고려하여 변호사, 법무법인 등의 소송대리인을 선임할 수 있다.</p><ol><li>중요한 법리적 쟁점이 있는 경우</li><li>정책적으로 중요한 사안에 관하여 다수의 소송이 제기된 경우</li><li>그 밖에 소송대리인을 선임하는 것이 적정하다고 판단되는 경우<br> ② 대표이사가 소송대리인을 선임하고자 하는 경우 지방계약법 및 서울문화재단 계약관련 규정에 따라 계약을 통해 선임한다.<br> ③ 대표이사가 변호사 또는 법무법인을 소송대리인으로 선임할 경우 별지 제3호서식, 별지 제4호서식에 따라 소송위임 계약서 및 소송위임장을 작성한다.<br> ④ 대표이사가 재단 직원을 소송대리인으로 선임할 경우 별지 제5호서식에 따라 소송위임장과 소송대리인 허가신청서를 작성한다.<br> ⑤ 제4조 각 항과 관련된 별지서식은 소송사무의 성격에 따라 계약자와 수임자 간 협의를 통해 수정할 수 있다.</li></ol><h2 id="article5" class="sr-only" tabindex="-1">제5조 (소송보수지급기준액) <a class="header-anchor" href="#article5" aria-label="Permalink to &quot;제5조 (소송보수지급기준액) {#article5 .sr-only}&quot;">​</a></h2><p><strong>제5조(소송보수지급기준액)</strong> ① 국가소송, 행정소송, 행정심판, 헌법소송사건 등의 보수지급은&quot;변호사 보수 규정&quot;(법무부훈령 제1379호)에 따른다. 단, 법령이나 현실여건의 변화 등을 감안하여 재단 및 소송대리인과 협의 하에 소송보수지급액을 산정할 수 있다.<br> ② 제1항의 소송사건 외 기타 소송의 착수금, 승소사례금, 인지대, 송달료 및 자문보수금은 사건의 난이도, 중요도, 예산 등을 고려하여 대표이사가 별도로 정하며, 법원에 납부하는 정액(실액)이 있는 항목의 경우는 실비 지급을 원칙으로 한다.</p><h2 id="article6" class="sr-only" tabindex="-1">제6조 (소송대리인의 의무) <a class="header-anchor" href="#article6" aria-label="Permalink to &quot;제6조 (소송대리인의 의무) {#article6 .sr-only}&quot;">​</a></h2><p><strong>제6조(소송대리인의 의무)</strong> ① 제4조에 따라 선임된 소송 대리인은 소송대리인의 소임 및 의무사항을 준수하기 위해 다음 각 호의 내용이 포함된 별지 제1호서식에 따른 청렴서약서를 제출하여야 하며 다음의 각 호 어느 하나에 해당하는 경우 재단은 계약 시기와 상관없이 소송 대리인과의 수임계약을 해지할 수 있다.</p><ol><li>금품수수, 부당한 알선, 청탁</li><li>재단과 이해관계가 상충되는 직무수행</li><li>이권 개입 등 직무의 부당이용</li><li>미공개 정보이용, 기타 공익에 반하는 활동</li><li>재단 소송사건 상대방의 소송 수임</li><li>재단 소송사건 상대방을 위한 법률 자문</li><li>재단 소송사건의 소송 수행 과정에서 알게 된 미공개 정보의 이용</li><li>그 밖에 재단 업무 또는 소송사무와 상충되는 업무의 수행</li></ol><p>② 소송대리인은 수임업무의 신의에 따라 소송사무 업무를 성실하게 수행하여야 한다.<br> ③ 소송대리인은 위촉 중 또는 해촉 후라도 서울문화재단의 소송사무 관련 업무에서 취득한 기밀 등 사건내용의 일체를 누설하여서는 안된다.</p><h2 id="article7" class="sr-only" tabindex="-1">제7조 (소송대리인 징계정보 조회) <a class="header-anchor" href="#article7" aria-label="Permalink to &quot;제7조 (소송대리인 징계정보 조회) {#article7 .sr-only}&quot;">​</a></h2><p><strong>제7조(소송대리인 징계정보 조회)</strong> ① 제4조에 따라 소송대리인을 선임하려는 경우에는 &quot;변호사법&quot;에 따라 설립된 대한변호사협회에 선임하려는 변호사 등의 징계에 관한 정보의 열람이나 복사를 신청하여야 한다.<br> ② 대표이사는 소송대리인이「변호사법」제90조(같은 법 제57조, 제58조의16 및 제58조의30에서 준용하는 경우를 포함한다)에 따른 징계를 받은 경우 혹은 다음 각 호의 구분에 따른 기간이 지나지 아니한 때에는 해당 소송대리인을 선임하지 아니한다.</p><ol><li>정직 : 5년</li><li>과태료 : 2년</li><li>견책 : 1년</li></ol><h2 id="article8" class="sr-only" tabindex="-1">제8조 (소관부서 장의 책무) <a class="header-anchor" href="#article8" aria-label="Permalink to &quot;제8조 (소관부서 장의 책무) {#article8 .sr-only}&quot;">​</a></h2><p><strong>제8조(소관부서 장의 책무)</strong> ① 소관부서의 장은 수행하는 소송사무에 있어 부당한 결론이 도출되지 않도록 적극적으로 업무에 임해야 하며 재단과 관련된 사항을 외부로 발설하지 않는 등 소송사무 일체의 비밀을 엄수하여야 한다.</p><h2 id="제2장-소송업무-수행절차" tabindex="-1">제2장 소송업무 수행절차 <a class="header-anchor" href="#제2장-소송업무-수행절차" aria-label="Permalink to &quot;제2장 소송업무 수행절차&quot;">​</a></h2><h2 id="article9" class="sr-only" tabindex="-1">제9조 (소송수행) <a class="header-anchor" href="#article9" aria-label="Permalink to &quot;제9조 (소송수행) {#article9 .sr-only}&quot;">​</a></h2><p><strong>제9조(소송수행)</strong> ① 소송사무와 관련된 업무는 사건이 발생한 소관부서의 소송수행자가 수행한다.<br> ② 대표이사는 소송사무 업무와 관련하여 2개 이상의 부서가 관련될 시 소송사무와 부서 간 연관성을 고려하여 소송사무처리 전담 소관부서를 정한다.<br> ③ 소송수행자는 소송업무 수행과 관련하여 대표이사가 선임한 소송대리인을 통해 관련 업무를 진행할 수 있으며, 소액사건‧단독사건 등 사건의 성격상 소관부서에서 직접 수행하는 것이 효율적이라고 인정되는 사건의 경우에는 직접 수행한다.</p><h2 id="article10" class="sr-only" tabindex="-1">제10조 (소송진행 상황의 보고) <a class="header-anchor" href="#article10" aria-label="Permalink to &quot;제10조 (소송진행 상황의 보고) {#article10 .sr-only}&quot;">​</a></h2><p><strong>제10조(소송진행 상황의 보고)</strong> ① 소송수행자 등은 해당 소송의 제소, 응소, 심급별 소송 결과 및 소송종결 사항 등의 내용을 별지 제2호서식에 따라 지체 없이 관리부서 및 대표이사에게 보고하여야 한다.<br> ② 소송 진행과 관련된 업무에 필요하다고 판단되는 경우 「국가를 당사자로 하는 소송업무 처리지침」(법무부예규 제1276호)을 준용한다.</p><h2 id="article11" class="sr-only" tabindex="-1">제11조 (소송고지 및 보전조치) <a class="header-anchor" href="#article11" aria-label="Permalink to &quot;제11조 (소송고지 및 보전조치) {#article11 .sr-only}&quot;">​</a></h2><p><strong>제11조(소송고지 및 보전조치)</strong> ① 소송고지 및 보전조치와 관련된 이행 여부 판단과 실행은 사건의 소관부서가 하는 것을 원칙으로 하며, 소관부서장의 판단에 따라 소송수행자가 진행할 수 있다.<br> ② 소송의 결과에 대하여 이해관계인이 있을 때에는 이를 고지하여 이해관계인이 소송참가의 기회를 갖도록 하여야 한다.<br> ③ 소송사건이 다른 부서의 사무와 관련이 있거나 소송결과가 그 부서에 영향을 미칠 것으로 인정되는 경우에는 해당 부서에 이를 통보하여 필요한 조치의 강구와 협조를 얻어야 한다.<br> ④ 장래의 강제집행을 보전하기 위하여 필요하다고 인정되는 경우 소송목적물 또는 채무자의 재산에 대하여 가압류 또는 가처분 등의 조치를 하여야 한다.</p><h2 id="article12" class="sr-only" tabindex="-1">제12조 (상소의 제기 등) <a class="header-anchor" href="#article12" aria-label="Permalink to &quot;제12조 (상소의 제기 등) {#article12 .sr-only}&quot;">​</a></h2><p><strong>제12조(상소의 제기 등)</strong> ① 소송수행자는 법원의 판결에 상소의 사유가 있는 경우에 그 사유와 소송대리인의 의견 등을 검토하여 정해진 기간 내에 상소를 제기하여야 한다.<br> ② 다음 각 호의 어느 하나에 해당하는 경우에는 상소를 포기할 수 있다.</p><ol><li>대법원 판례 등에 비추어 승소의 가능성이 거의 없는 경우</li><li>상소의 이익이 경미한 경우</li><li>대표이사 판단에 따라 상소가 필요없다고 판단되는 경우</li></ol><h2 id="article13" class="sr-only" tabindex="-1">제13조 (화해 등) <a class="header-anchor" href="#article13" aria-label="Permalink to &quot;제13조 (화해 등) {#article13 .sr-only}&quot;">​</a></h2><p><strong>제13조(화해 등)</strong> ① 소관부서는 민사소송법 제225조에 따라 소송담당재판부의 화해권고결정을 받았을 경우 다음 각 호에 따라 소송대리인의 자문을 받아 화해권고결정을 수용할 수 있다.</p><ol><li>상소(항고를 포함한다)를 통해 화해권고결정 이상의 소송실익을 확보할 수 없다고 판단될 때</li><li>소송의 계속 진행이 재단의 운영방향, 업무실익, 사회적 가치 실현에 반한다고 판단될 때</li></ol><h2 id="제3장-소송비용의-회수" tabindex="-1">제3장 소송비용의 회수 <a class="header-anchor" href="#제3장-소송비용의-회수" aria-label="Permalink to &quot;제3장 소송비용의 회수&quot;">​</a></h2><h2 id="article14" class="sr-only" tabindex="-1">제14조 (소송비용의 회수) <a class="header-anchor" href="#article14" aria-label="Permalink to &quot;제14조 (소송비용의 회수) {#article14 .sr-only}&quot;">​</a></h2><p><strong>제14조(소송비용의 회수)</strong> ① 소송수행자 등은 승소 판결이 확정된 날로부터 60일 이내에 소송비용액 확정결정 신청서를 관할 제1심 법원에 제출하여야 한다. 다만, 일부 패소 등으로 인해 재단의 소송비용 부담이 더 많이 예상되거나 부담여부가 불분명한 경우 등에는 소송비용액 확정결정 신청여부를 결정하되, 상대방이 이미 소송비용액 확정결정 신청을 한 경우에는 소송비용액 계산서를 제출해야 한다.<br> ② 소관부서의 장은 법원으로부터 소송비용액확정 결정문이 송달된 경우 60일 이내에 지체없이 등기우편으로 상대방에게 소송비용 납부 최고 등을 하여 소송비용을 회수하고 필요한 경우에는 강제집행 등의 조치를 하여야 한다.<br> ③ 패소 판결에 따라 상대방으로부터 소송비용의 지급을 청구받은 경우 지출부서에 소송비용 지급 청구서와 소송비용액확정 결정서를 첨부하여 해당 소송비용액의 지급을 의뢰하여야 한다.</p><h2 id="article15" class="sr-only" tabindex="-1">제15조 (소송비용의 회수의 예외) <a class="header-anchor" href="#article15" aria-label="Permalink to &quot;제15조 (소송비용의 회수의 예외) {#article15 .sr-only}&quot;">​</a></h2><p><strong>제15조(소송비용의 회수의 예외)</strong> ① 재단은 승소판결이 확정된 사건이 다음 아래 어느 하나에 해당하는 경우 소송비용의 회수를 포기할 수 있다.</p><ol><li>청구할 수 있는 소송비용의 합계액이 30만원 미만으로 소액인 경우</li><li>상대방의 법률적 착오 또는 무지로 인하여 서울문화재단이 당사자로 지정된 경우</li><li>상대방에게 경제적 자력이 없는 경우. 다만, 소송수행자가 법원에 소송비용액 확정결정 신청서를 제출하기 전까지 상대방이 해당세관에 「국민기초생활 보장법」에 따른 수급권자 또는 「채무자 회생 및 파산에 관한 법률」에 따라 개인회생 및 파산, 면책 결정을 받은 자임을 입증하는 서류를 제출하는 등 경제적인 어려움을 소명할 수 있는 기타 객관적인 자료를 제출한 경우로 한정한다.</li><li>상대방이 사망, 실종, 행방불명 등으로 회수가 불가능한 경우</li><li>소송비용 회수에 소요되는 비용보다 회수해야 할 비용이 적은 경우</li><li>기타 상대방에게 소송비용을 부담시키는 것이 적정하지 않다고 인정되는 경우</li></ol><h2 id="article16" class="sr-only" tabindex="-1">제16조 (소송비용 심의위원회) <a class="header-anchor" href="#article16" aria-label="Permalink to &quot;제16조 (소송비용 심의위원회) {#article16 .sr-only}&quot;">​</a></h2><p><strong>제16조(소송비용 심의위원회)</strong> ① 제15조 1항 6호에 해당하는 사항이나 그 밖에 소송비용 회수와 관련된 중요한 사항을 결정하기 위하여 대표이사가 필요하다고 판단되는 경우 외부위원이 포함된 7인 이내의 심의위원을 위촉하여 소송비용 심의위원회를 개최할 수 있다.<br> ② 소송비용 심의위원회의 외부위원은 법률, 경영, 문화예술 등 해당 소송사무 처리와 관련하여 유사한 자격 또는 경력을 갖춘 사람으로서 최소 1명 이상을 위촉하여야 한다.<br> ③ 소송비용 심의위원회의 위원장은 외부위원 중 호선으로 결정한다. 단, 외부위원이 1명일 경우 해당 외부위원을 위원장으로 임한다.</p><h2 id="addendum1" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum1" aria-label="Permalink to &quot;부칙 {#addendum1 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2022. 5. 26.&gt;<br> 제1조(시행일) 이 내규는 대표이사의 승인을 얻은 날로부터 시행한다.</p><p><strong>[별지 제1호]</strong><strong>청렴서약서</strong></p><table style="border-collapse:collapse;border:1px solid #000;width:100%;table-layout:fixed;"><colgroup><col style="width:642px;"></colgroup><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p><p style="margin:0;text-align:center;"><strong>청 렴 서 약 서</strong></p><p style="margin:0;text-align:left;">본인은 서울문화재단 소송대리인으로서 아래와 같이 서약합니다.</p><p style="margin:0;text-align:left;"></p><p style="margin:0;text-align:left;">ⓛ 금품·향응 수수, 부당한 알선·청탁을 하지 않겠습니다.</p><p style="margin:0;text-align:left;">② 서울문화재단의 이해관계와 상충되는 직무수행을 하지 않겠습니다.</p><p style="margin:0;text-align:left;">③ 이권 개입 등 직무의 부당한 이용을 하지 않겠습니다.</p><p style="margin:0;text-align:left;">④ 미공개 정보이용 등 기타 공익에 반하는 활동을 하지 않겠습니다.</p><p style="margin:0;text-align:left;">⑤ 성희롱, 성폭력 관련 처분 및 사회적 물의를 일으킨 사실이 없음을 확인하며 과업 중 성적 언동을 하지 않는 등 성희롱‧성폭력 예방을 위해 최선을 다하겠습니다.</p><p style="margin:0;text-align:left;">⑥ 소송사무업무와 관련하여 소송대리인의 의무(내규 제6조 등)를 다하겠습니다.</p><p style="margin:0;text-align:left;"></p><p style="margin:0;text-align:left;">만약 위 서약에 위반되는 행위를 하는 경우에는 그 직에서 해촉되더라도 이의를 제기하지 않겠습니다.</p><p style="margin:0;text-align:left;"></p><p style="margin:0;text-align:center;">년 월 일</p><p style="margin:0;text-align:left;"></p><p style="margin:0;text-align:left;">서 약 자 소속 :</p><p style="margin:0;text-align:left;">성명 : (서명)</p><p style="margin:0;text-align:left;"></p></th></tr></table><p><strong>[별지 제2호]</strong><strong>소송진행상황 보고서</strong></p><p style="text-align:center;">소 송 진 행 상 황</p><table style="border-collapse:collapse;border:1px solid #000;width:100%;table-layout:auto;"><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">심 급</p></th><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">사건번호</p></th><th colspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">소송발생부서</p><p style="margin:0;text-align:center;">(소송수행실무자)</p></th><th colspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">소송대리인</p></th><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">소송결과</p></th><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">상소(확정)</p><p style="margin:0;text-align:center;">여 부</p></th></tr><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">1 심</p></th><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">호</p></th><th colspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></th><th colspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></th><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></th><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></th></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">2 심</p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">호</p></td><td colspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td colspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">3 심</p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">호</p></td><td colspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td colspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">환송심</p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">호</p></td><td colspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td colspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">사건명</p></td><td colspan="3" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td colspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">소 가</p></td><td colspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">당사자</p></td><td colspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">원 고</p></td><td colspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">피 고</p></td><td colspan="3" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">( )참가인</p></td></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td colspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td colspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td colspan="3" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">사</p><p style="margin:0;text-align:left;"></p><p style="margin:0;text-align:center;">건</p><p style="margin:0;text-align:left;"></p><p style="margin:0;text-align:center;">개</p><p style="margin:0;text-align:left;"></p><p style="margin:0;text-align:center;">요</p></td><td colspan="7" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p><p style="margin:0;text-align:left;">1. 청구취지요지</p><p style="margin:0;text-align:left;"></p><p style="margin:0;text-align:left;">2. 청구원인요지</p><p style="margin:0;text-align:left;"></p><p style="margin:0;text-align:left;">3. 청구취지변경요지</p><p style="margin:0;text-align:left;"></p></td></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">쟁</p><p style="margin:0;text-align:left;"></p><p style="margin:0;text-align:center;">점</p></td><td colspan="7" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td></tr></table><p><strong>[별지 제3호]</strong><strong>소송위임계약서</strong></p><table style="border-collapse:collapse;border:1px solid #000;width:100%;table-layout:fixed;"><colgroup><col style="width:642px;"></colgroup><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p><p style="margin:0;text-align:center;">소 송 위 임 계 약 서</p><p style="margin:0;text-align:left;"></p><p style="margin:0;text-align:center;">서울문화재단(이하󰡒재단󰡓이라 칭함)과 변호사(법무법인) ○○○(이하󰡒소송대리인󰡓이라 칭함)은</p><p style="margin:0;text-align:center;">원고 ○○○, 피고 ○○○간의󰡒 󰡓사건에 관하여 다음과 같이 소송위임계약을 체결한다.</p><p style="margin:0;text-align:left;"></p><p style="margin:0;text-align:left;">제1조󰡒재단󰡓은 󰡒소송대리인󰡓에게 위 사건의 제○심 소송대리를 위임하고 별도로 소송위임장을 교부한다.</p><p style="margin:0;text-align:left;">제2조󰡒재단󰡓은 󰡒소송대리인󰡓에게 위임사무처리의 착수금으로 금 원을 지급한다.</p><p style="margin:0;text-align:left;">제3조󰡒재단󰡓은 󰡒소송대리인󰡓에게 위임사무처리상 필요한 인지대, 예납금(송달료, 법원의 납부명령에 의한 검증료, 감정료), 기록등사료, 출장여비 등을 지급한다.</p><p style="margin:0;text-align:left;">제4조  위임사무처리가 전부승소일 때에는 승소의 정도, 소송수행의 난이도 등을 참작하여 지급한다.</p><p style="margin:0;text-align:left;">제5조󰡒소송대리인󰡓은 수임사항 중 취하, 반소의 제기, 화해, 청구의 포기, 상소권 포기 등 중요한 소송행위를 함에 있어서는 미리󰡒재단󰡓의 동의를 받아야 한다.</p><p style="margin:0;text-align:left;">제6조󰡒소송대리인󰡓은 수임사건의 진행상황을 수시로 󰡒재단󰡓에게 통보하여야 한다.</p><p style="margin:0;text-align:left;">제7조󰡒소송대리인󰡓은 수임사무를 신의에 따라 성실하게 처리하여야 한다.</p><p style="margin:0;text-align:left;">제8조󰡒소송대리인󰡓은 업무상 지득한 󰡒재단󰡓의 기밀을 누설하지 못한다.</p><p style="margin:0;text-align:left;">제9조 이 계약에 명시되지 않은 사항은 서울문화재단 소송사무처리규정에 의한다.</p><p style="margin:0;text-align:left;"></p><p style="margin:0;text-align:left;">이 계약을 증하기 위하여 이 계약서 2통을 작성하고 󰡒재단󰡓과 󰡒소송대리인󰡓은 각 1통씩 보관한다.</p><p style="margin:0;text-align:left;"></p><p style="margin:0;text-align:center;">년 월 일</p><p style="margin:0;text-align:left;"></p><p style="margin:0;text-align:right;">󰡒재단󰡓주소 : 서울시 동대문구 청계천로 517 서울문화재단 대표이사 ○○○ (인)</p><p style="margin:0;text-align:left;"></p><p style="margin:0;text-align:right;">󰡒소송대리인󰡓주소 : OOO OOO OOO OOO OOO 변 호 사(법무법인) ○○○ (인)</p><p style="margin:0;text-align:left;"></p></th></tr></table><p><strong>[별지 제4호]</strong><strong>소송위임장</strong></p><table style="border-collapse:collapse;border:1px solid #000;width:100%;table-layout:auto;"><tr><th colspan="3" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">소 송 위 임 장</p></th></tr><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">사 건</p></th><th colspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"><strong></strong></p></th></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">당 사 자</p></td><td colspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"><strong></strong>채 권 자 재단법인 서울문화재단</p><p style="margin:0;text-align:left;">채 무 자 <strong></strong></p></td></tr><tr><td colspan="3" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">위 사건에 관하여 아래의 수임인을<strong></strong>채권자<strong></strong>소송대리인으로 선임하고, 아래와 같은 권한을 수여합니다.</p></td></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">수 임 인</p></td><td colspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;">OOOOO</p><p style="margin:0;text-align:left;">[주소]</p><p style="margin:0;text-align:left;">[전화] 02-000-0000, 팩스: 0000-000-0000</p></td></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">담당 변호사</p></td><td colspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">수 권 사 항</p></td><td colspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;">- 모든 소송행위</p><p style="margin:0;text-align:left;">- 반소의 제기 및 응소</p><p style="margin:0;text-align:left;">- 재판상 및 재판 외의 화해, 소의 취하, 청구의 포기 및 인낙, 소송 탈퇴</p><p style="margin:0;text-align:left;">- 복대리의 선임</p><p style="margin:0;text-align:left;">- 목적물의 수령</p><p style="margin:0;text-align:left;">- 공탁, 공탁물 및 그 이자의 반환청구와 수령</p><p style="margin:0;text-align:left;">- 담보권행사 최고신청, 담보 취소신청, 동 신청에 대한 동의, 담보 취소 결정 정본의 수령, 동 취소 결정에 대한 항고권 포기</p><p style="margin:0;text-align:left;">- 상소의 제기 또는 그 취하에 관한 권한</p><p style="margin:0;text-align:left;">- 소송비용액확정신청 및 이에 대한 응소</p><p style="margin:0;text-align:left;">- 가압류ㆍ가처분신청, 위 결정에 대한 이의 및 취소신청, 이에 대한 응소</p><p style="margin:0;text-align:left;">- 경매의 참가, 배당금의 수령 등 경매와 관련된 일체의 행위</p><p style="margin:0;text-align:left;">- 집행정지신청 및 이에 대한 즉시항고</p><p style="margin:0;text-align:left;">- 권리행사최고신청</p><p style="margin:0;text-align:left;">- 제소명령신청</p></td></tr><tr><td colspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">2000 년 00 월 00 일</p><p style="margin:0;text-align:left;">위임인 재단법인 서울문화재단 (인)</p><p style="margin:0;text-align:left;">서울 동대문구 청계천로 517 (용두동)</p><p style="margin:0;text-align:left;">대표이사 O O O</p><p style="margin:0;text-align:left;"></p><p style="margin:0;text-align:left;">서울OOOO법원 독촉계 귀중</p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td></tr><tr><td colspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p><table style="border-collapse:collapse;border:1px solid #000;width:100%;table-layout:fixed;"><colgroup><col style="width:153px;"></colgroup><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">변호사회경유</p></th></tr><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;"><strong>별첨(전자경유서)</strong></p></th></tr></table><p style="margin:0;text-align:left;"></p></td></tr></table><p><strong>[별지 제5호]</strong><strong>소송대리허가신청과 소송위임장</strong></p><p>소송대리허가신청과 소송위임장<br> ［담당재판부 : 제 민사부(단독)］<br> 사 건 20○○가단(합, 소)○○○○ 구상금<br> 원 고 ○○○<br> 피 고 ○○○</p><p>이 사건에 관하여 원고(또는 피고)는 다음과 같이 소송대리허가신청과 소송위임을 합니다.</p><ul><li>다음 -</li></ul><ol><li><p>소송대리허가신청<br> 가. 소송대리할 사람의 이름 : ○○○ (주민등록번호 또는 한자)<br> 서울 서초구 서초대로 300 (우편번호 : ○○○-○○○)<br> 전화번호ㆍ휴대전화번호 :<br> 팩시밀리번호 또는 전자우편주소 :<br> 나. 신청이유(해당란에 ✔ 해 주시기 바랍니다)<br> □ 당사자의 배우자 또는 4촌 안의 친족으로서 밀접한 생활관계를 맺고 있음<br> □ 당사자와 고용 등의 계약관계를 맺고 그 사건에 관한 일반사무를 처리ㆍ보조하여 왔음</p></li><li><p>위임 사항</p></li></ol><ul><li>모든 소송행위</li><li>반소의 제기 및 응소</li><li>재판상 및 재판 외의 화해, 소의 취하, 청구의 포기 및 인낙, 소송 탈퇴</li><li>복대리의 선임</li><li>목적물의 수령</li><li>공탁, 공탁물 및 그 이자의 반환청구와 수령</li><li>담보권행사 최고신청, 담보 취소신청, 동 신청에 대한 동의, 담보 취소 결정정본의 수령, 동 취소 결정에 대한 항고권 포기</li><li>상소의 제기 또는 그 취하에 관한 권한</li><li>소송비용액확정신청 및 이에 대한 응소</li><li>가압류ㆍ가처분신청, 위 결정에 대한 이의 및 취소신청, 이에 대한 응소</li><li>경매의 참가, 배당금의 수령 등 경매와 관련된 일체의 행위</li><li>집행정지신청 및 이에 대한 즉시항고</li><li>권리행사최고신청</li><li>제소명령신청</li></ul><p>첨부서류</p><ol><li>재직증명서 1통</li><li>가족관계증명서 1통</li><li>주민등록표 등본 1통</li></ol><p>20○○. ○○. ○○.</p><p>신청인 겸 위임인 원고(또는 피고) ○○○ (날인 또는 서명)<br> 연락처 : 000-0000-0000</p><p>○○지방법원 (○○지원) 제 ○민사부(단독) 귀중</p>',67)]))}const m=l(o,[["render",d]]);export{b as __pageData,m as default};
